<?php

declare(strict_types=1);

namespace App\Service\Filing;

use App\Entity\FilingPackagePart;
use App\Enum\SignatureStatus;
use App\Service\Pdf\PdfTextProbe;
use App\Service\Pdf\ProcessSandbox;
use App\Service\Pdf\QpdfRunner;

/**
 * Ties a signed upload to the generated file it should be.
 *
 * Every word of every generated page has to read, in order, on the same page of
 * the signed file (PageTextComparison, after PdfTextProbe::normalize). A changed,
 * missing or moved word, a missing or moved page, or another part's token is a
 * mismatch. A visible signature is read without its widget when its words would
 * otherwise break the comparison.
 *
 * PRESENT_MATCHED needs the generated bytes as a prefix (an incremental
 * signature), the same text with nothing added, no appended page and the part
 * token present. Anything a signing tool may legitimately do beyond that, such as
 * rewriting the file, adding text to a page, appending a signature page or
 * dropping the token, is PRESENT_PROBABLE: the lawyer confirms after reading the
 * notes that say what was tolerated. Notes carry page numbers and counts, never
 * the words themselves.
 */
final class SignedPartMatcher
{
    public function __construct(
        private readonly QpdfRunner $qpdf,
        private readonly PdfTextProbe $textProbe,
        private readonly FilingPartWriter $writer,
        private readonly ProcessSandbox $sandbox,
    ) {}

    public function match(FilingPackagePart $part, string $signedPath, int $signedPageCount): SignedPartMatch
    {
        $unsignedPath = $this->writer->absolute($part->getUnsignedPath());
        if (!is_file($unsignedPath) || $signedPageCount < $part->getPageCount()) {
            return new SignedPartMatch(SignatureStatus::MISMATCH);
        }

        $generated = $this->textProbe->pageTexts($unsignedPath);
        $comparison = PageTextComparison::compare($generated, $this->textProbe->pageTexts($signedPath));
        if ($comparison === null || !$comparison->exact()) {
            $comparison = self::better($comparison, $this->compareWithoutSignatureWidgets($generated, $signedPath));
        }
        if ($comparison === null) {
            return new SignedPartMatch(SignatureStatus::MISMATCH);
        }

        // Read from the generated file rather than the row: a part carried into a
        // rebuilt version has a new row token but the same file.
        $expectedToken = $this->qpdf->readInfoKey($unsignedPath, QpdfRunner::PART_ID_KEY);
        $signedToken = $this->qpdf->readPartToken($signedPath);
        foreach ($signedToken as $found) {
            if ($found !== null && $found !== $expectedToken) {
                return new SignedPartMatch(SignatureStatus::MISMATCH);
            }
        }
        $tokenMissing = $expectedToken !== null && $signedToken['info'] === null && $signedToken['xmp'] === null;

        $textless = in_array('', $generated, true);
        // Pages without text are compared only by position; without the token the
        // text left cannot tell one generated part from another.
        if ($tokenMissing && $textless) {
            return new SignedPartMatch(SignatureStatus::MISMATCH);
        }

        $prefix = $this->startsWithGeneratedBytes($part, $signedPath);
        $method = $prefix ? SignedPartMatch::METHOD_PREFIX : SignedPartMatch::METHOD_TEXT;
        $warnings = $textless ? ['filing.signature.warning.textless_pages'] : [];
        if ($prefix && $comparison->exact() && !$tokenMissing) {
            return new SignedPartMatch(SignatureStatus::PRESENT_MATCHED, $method, $warnings);
        }

        return new SignedPartMatch(SignatureStatus::PRESENT_PROBABLE, $method, $warnings, self::notes($comparison, $tokenMissing));
    }

    /**
     * A visible signature placed over the text interleaves its own words with the
     * page words. The generated file has no signature widget, so its text has to
     * read the same once they are dropped.
     *
     * @param list<string> $generated
     */
    private function compareWithoutSignatureWidgets(array $generated, string $signedPath): ?PageComparisonResult
    {
        $copy = $this->sandbox->tempPath('pdf');
        if (!$this->qpdf->withoutSignatureWidgets($signedPath, $copy)) {
            return null;
        }

        return PageTextComparison::compare($generated, $this->textProbe->pageTexts($copy));
    }

    private static function better(?PageComparisonResult $raw, ?PageComparisonResult $copy): ?PageComparisonResult
    {
        if ($copy === null) {
            return $raw;
        }
        if ($raw === null) {
            return $copy;
        }

        return $copy->insertedWordCount() < $raw->insertedWordCount() ? $copy : $raw;
    }

    /**
     * @return list<array{key: string, params: array<string, string|int>}>
     */
    private static function notes(PageComparisonResult $comparison, bool $tokenMissing): array
    {
        $notes = [];
        foreach ($comparison->insertedByPage as $page => $words) {
            $notes[] = ['key' => 'filing.signature.note.text_added', 'params' => ['%page%' => $page, '%count%' => count($words)]];
            if (preg_grep('/\p{N}/u', $words) !== []) {
                $notes[] = ['key' => 'filing.signature.note.text_added_with_digits', 'params' => ['%page%' => $page]];
            }
        }
        if ($comparison->extraPages > 0) {
            $notes[] = ['key' => 'filing.signature.note.pages_appended', 'params' => ['%count%' => $comparison->extraPages]];
        }
        if ($tokenMissing) {
            $notes[] = ['key' => 'filing.signature.note.part_id_missing', 'params' => []];
        }

        return $notes;
    }

    private function startsWithGeneratedBytes(FilingPackagePart $part, string $signedPath): bool
    {
        $length = $part->getUnsignedBytes();
        if ((int) filesize($signedPath) <= $length) {
            return false;
        }
        $prefix = file_get_contents($signedPath, false, null, 0, $length);

        return is_string($prefix) && hash_equals($part->getUnsignedSha256(), hash('sha256', $prefix));
    }
}
